"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["9708"],{1954(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>h,frontMatter:()=>s,contentTitle:()=>l,toc:()=>c,assets:()=>r});var a=JSON.parse('{"id":"how-to/hardware/samples/hl-stnucleo-mqtt-c","title":"Using MQTT with an HL Shield and a ST Nucleo","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/hardware/samples/hl-stnucleo-mqtt-c.md","sourceDirName":"how-to/hardware/samples","slug":"/how-to/hardware/samples/hl-stnucleo-mqtt-c","permalink":"/personal-av-docs/docs/how-to/hardware/samples/hl-stnucleo-mqtt-c","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/hardware/samples/hl-stnucleo-mqtt-c.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Using MQTT with an HL Shield and a ST Nucleo","sidebar_label":"Using MQTT with an HL Shield and a ST Nu","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/howto/hardware/samples/hl-stnucleo-mqtt-c","format":"md"}}'),i=t(4848),o=t(8453);let s={title:"Using MQTT with an HL Shield and a ST Nucleo",sidebar_label:"Using MQTT with an HL Shield and a ST Nu",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/howto/hardware/samples/hl-stnucleo-mqtt-c",format:"md"},l,r={},c=[];function d(e){let n={a:"a",code:"code",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(n.p,{children:[":::note Edition\n",(0,i.jsx)(n.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,i.jsx)(n.a,{href:"https://doc.airvantage.net/av/howto/hardware/samples/hl-stnucleo-mqtt-c",children:"Original page"}),".\n:::"]}),"\n",(0,i.jsxs)(n.p,{children:['Using MQTT with an HL Shield and a ST Nucleo\nThis article explains how to send data to AirVantage for mbed devices using MQTT and an HL shield. It will focus on two boards: the ST Nucleo and the HL Shield. As the ST Nucleo board is a microcontrol without any IP stack, it requires to use the HL one. Consequently, all the interactions is done using AT commands. You can see more about this, in the Step 3 below.\n1 /\nSetup\n2 /\nDesign\n3 /\nImplementing\nPrerequisite\nYou must have:\nA basic knowledge of MQTT. See the other tutorials about MQTT for airvantage and specifically\nMQTT API\n.\nA basic knowledge of c.\nA basic knowledge on mbed development\nAn Internet access with an HL6* or an HL8 shield\nA ST Nucleo\nL053R8\n(the software has been specifically developed with this target. It may work with another ST Nucleo board with slight changes).\n*) For HL6, the sample must be modified (function\nMQTTClient::getIMEI\nin the file\nMQTTClient.cpp\n) to get the IMEI. The command\nAT+CGSN\nmust be used instead of the command\nAT+KGSN=0\n.\nStep 1: Setup Hardware\nThe ST Nucleo L053R8 has been used for the development. There are some particularities about this board.\nST Nucleo (L053R8)\nBy default, the RX, TX pins are on CN3 and not on CN9. It means that the pins layout is not fully Arduino compatible. You can\u2019t plug the two boards directly. You need to connect them using wires.\nAnother way is to modify the Solder Bridge as described in the following document.\nUM1724 - User manual ST Nucleo\nHL Shield\nThe HL shield must have their inputs/outputs powered by the ST Nucleo board. If not, the TX signal from the HL shield will not be read by the ST Nucleo board.\nFor more information, you can check in the file\nDesign of the DistriKit Board\n.\nConnection\nThe 2 boards need to be connected. You must follow this wiring:\nST Nucleo\nHL Shield\nTX (CN3)\nRX (XP4)\nRX (CN3)\nTX (XP4)\nIOREF (CN6)\nIOREF (XP3)\nGND (CN6)\nGND (XP3)\nStep 2: Design your application\nAn\napplication model\naims to explain to AirVantage how to deal with the device about communication and authentication and managing the data: variable, settings or commands.\nIf you don\u2019t supply such information, the server will not understand and be able to use the raw data from your device.\nThis application is already deployed on AirVantage in the public repository under the name Distri Kit version 1.0.0. You can use this one or create a new application for your company using an other name.\nDefine your data\nFirst of all, to be able to send and receive data, you have to describe your data to AirVantage.\nHere is the description, you just need to change the\ntype\nvalue with a unique identifier for your application and the\nname\nand\nrevision\nwith the appropriate values for your use case.\nYou can modify the\n<data>\narea. Once it matches your needs, save everything as\nmodel.app\n.\nDon\u2019t modify the asset id as it is used in the source code application or modify it accordingly.\n<?xml version="1.0" encoding="ISO-8859-1"?>\n<app:application\nxmlns:app="',(0,i.jsx)(n.a,{href:"http://www.sierrawireless.com/airvantage/application/1.0",children:"http://www.sierrawireless.com/airvantage/application/1.0"}),'"\ntype="com.test.airvantage.app"\nname="AirVantage Greenhouse"\nrevision="0.0.1">\n<capabilities>']}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:'&lt;communication&gt;\n  &lt;protocol comm-id="IMEI" type="MQTT" /&gt;\n&lt;/communication&gt;\n\n&lt;data&gt;\n  &lt;encoding type="MQTT"&gt;\n    &lt;asset default-label="Street Light" id="st"&gt;\n      &lt;variable default-label="Light Control" path="lightstatus" type="string"/&gt;\n      &lt;variable default-label="Light Sensor" path="lightsensor" type="int"/&gt;\n      &lt;variable default-label="Output Power" path="power" type="int"/&gt;\n      &lt;variable default-label="Failure Detected" path="failuredetected" type="boolean"/&gt;\n      &lt;command default-label="Manual OFF" id="modeoff"&gt;\n      &lt;/command&gt;\n      &lt;command default-label="Mode Auto" id="modeauto"&gt;\n      &lt;/command&gt;\n      &lt;command default-label="Manual ON" id="modeon"&gt;\n      &lt;/command&gt;\n    &lt;/asset&gt;\n  &lt;/encoding&gt;\n&lt;/data&gt;\n'})}),"\n",(0,i.jsx)(n.p,{children:"</capabilities>\n</app:application>\nCreate your application package\nZip this file, mine is named\nmodel.app.zip\nGo on Develop Activity > My Apps\nClick on the Release button\nRelease your application\nSelect your file model.app.zip\nOpen Advanced settings and select\nI want to publish my application after releasing it\nFinally, click on Start\nEdit your system\nGo on Inventory > Systems\nSelect your system and click on the Edit icon\nSearch your application\nClick on Search application\nIn the new dialog box, select the My Application tab\nSearch your application using its name (AirVantage Greenhouse)\nAssociate your application to your system\nClick on the application to select it.\nClick on the padlock and configure the password.\nClick on Save in the right top corner\nClick on the Monitor icon to monitor your system\nStep 3: Implementing an application\nIt is now time to write an application for the ST Nucleo.\nYou can have a look about\nusing MQTT in AirVantage\n, if you want to have a description about the serialisation details.\nThis C sample shows how to use MQTT to communicate with AirVantage.\nThe software architecture\nTo serialize the MQTT messages, we used the embedded Paho library.\nWe have added a higher level layer to supply API to manage the MQTT connection which implements each MQTT message.\nWe hadn\u2019t implemented the SUSCRIBE, UNSUSCRIBE because it is not required by the AirVantage server and the DISCONNECTED message as well.\nFinally, the application initializes the uart and declares a callback to receive the commands sent from AirVantage and it publishes the data by using the MQTT client layer.\nHere a more details information about how to use the MQTT client API and how to configure the UART used to communicate with the HL.\nThe Application\nThe application configure the uart and loop to send data."}),"\n",(0,i.jsxs)(n.ol,{children:["\n",(0,i.jsx)(n.li,{children:"Declare and Configure a Serial object\n//------------------------------------\n// Hyperterminal configuration\n// 115200 bauds, 8-bit data, no parity\n//------------------------------------\nSerial pc(SERIAL_TX, SERIAL_RX);\npc.baud(115200);"}),"\n",(0,i.jsx)(n.li,{children:"Start the MQTT Client\nMQTTClient client(server, &callback, password, port, &pc, apn);"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:'while(1)\n{\nif(client.connected == true)\n{\n...\nclient.pub ("home.alarm_threshold", "3.65");\n...'}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{children:"  }\n"})}),"\n",(0,i.jsx)(n.p,{children:"};\nThe MQTT Client\nInitialization\nThe initial declaration of the callback has been done here:\nMQTTClient client(server, &callback, password, port, &pc, apn);\nThe MQTT client can now use the uart to analyze the byte received from the connection.\nThe callback function here will be used to received the notification when a new command will be received."}),"\n",(0,i.jsxs)(n.ol,{children:["\n",(0,i.jsx)(n.li,{children:"Attach a callback\n// Setup a serial interrupt function to receive data\npc.attach(this,&MQTTClient::Rx_interrupt, Serial::RxIrq);"}),"\n",(0,i.jsx)(n.li,{children:"Implement a callback\nThis callback extracts the MQTT message from the bytes received from the HL.\n// Interupt Routine to read in data from serial port\nvoid MQTTClient::Rx_interrupt()\n{\n// Loop just in case more than one character is in UART's receive FIFO buffer\nwhile ((pc.readable()) )\n{\nrx_buffer[rx_in] = pc.getc();\nrx_in = (rx_in + 1) % BUFFER_SIZE;\n}\nreturn;\n}\nHow the MQTT Client deals with MQTT messages\nWith the HL module, you have to program your software sequentially (i.e. each task must be completed before dealing with the next one).\nYou can\u2019t do threaded programming to manage the HL.\nYou need to wait the response of each AT command to do the next task.\nThe MQTT client is designed basically as follow:"}),"\n",(0,i.jsx)(n.li,{children:"Connect\nThe function\nMQTTClient::connect\nfollow the pattern of the TCP connection.\nYou can see those steps in the tutorial\nHow to send data to AirVantage with the HL shield in standalone\n.\nThe embedded application is launched only after having received a CONNACK message from AirVantage (with or without any error)."}),"\n",(0,i.jsx)(n.li,{children:'Publish\nThe function\nMQTTClient::pub\nhas been designed for one value or four values to be send in the same time.\nThe generation of the JSON payload is very simplified.\nThe JSON format is:\n{"machine.temperature": 23.2, "machine.humidity": 70}'}),"\n",(0,i.jsx)(n.li,{children:"Ping\nThe function is called every 30 seconds to keep alive the connection."}),"\n",(0,i.jsx)(n.li,{children:"Receive\nThe function\nMQTTClient::recvData\nis called every time in the loop. It checks if a command has been received.\nFirstly, it checks if one byte or more has been received.\nThen, it decodes it to know the type of the message.\nWhen it receives the rest of the message, it decodes the size and parses the full message.\nOnce the full message has been received, it extract from the AT command result the full MQTT message and supply the payload to the callback.\nFinally, when a PUBLISH message has been received, it calls a callback function in main.cpp to decode it and then changes to the mode wanted by the users."}),"\n",(0,i.jsx)(n.li,{children:"Decode Data\nThis function is used to decode the message received by the HL from the server. It can be a CONNACK, a PING_RESP or a PUBLISH message.\nHow MQTT client communicates with HL Shield\nThe MQTT Client communicates with HL Shield using the AT Commands. By this way, no IP Stack is required from the host processor."}),"\n",(0,i.jsx)(n.li,{children:"Check if the SIM card is well inserted\nCommand:\nAT+CPIN?\nResponse expected:\n+CPIN: READY\nOK"}),"\n",(0,i.jsx)(n.li,{children:"Configure the APN\nCommand for HL8\nAT+KCNXCFG=1,\u201CGPRS\u201D,\u201D internet.maingate.se\u201D,\u201C\u201D,\u201C\u201D,IPV4,\u201C0.0.0.0\u201D\nCommand for HL6\nAT+KCNXCFG =0,\u201CGPRS\u201D,\u201Cinternet.maingate.se\u201D,\u201C\u201D,\u201C\u201D,\u201C0.0.0.0\u201D\nResponse expected:\nOK"}),"\n",(0,i.jsx)(n.li,{children:"Configure the address of the server\nCommand:\nAT+KTCPCFG=1,0,\u201D eu.airvantage.net\u201D,1883\nResponse expected:\n+KTCPCFG: 1\nOK"}),"\n",(0,i.jsx)(n.li,{children:"Launch a TCP connection\nCommand:\nAT+KTCPCNX=1\nResponse expected:\nOK"}),"\n",(0,i.jsx)(n.li,{children:"Send data with the size of the payload\nAt the end of each payload, it must be finished with \u2018\\r\\n\\r\\n\u2019. It means that the size of the data send is size of the payload + size of \u2018\\r\\n\\r\\n\u2019 (i.e. 8 bytes). For a payload of 55 bytes we must send 63 bytes. 55 + 8 = 63 bytes.\nCommand:\nAT+KTCPSND=1,63\nResponse expected:\nCONNECT\n[55 bytes of data\u2026.]\\r\\n\\r\\n\u2013EOF\u2013Pattern\u2013\nOK"}),"\n",(0,i.jsx)(n.li,{children:"The transmission is finished when the application sends this pattern \u2013EOF\u2013Pattern\u2014"}),"\n",(0,i.jsx)(n.li,{children:"Receive data, the application is informed by a notification from the HL\n+KTCP_DATA: 1,137\nIt means that 137 bytes has been received. To retrieve the data:\nCommand:\nAT+KTCPRCV=1,137\nResponse expected:\nCONNECT\n359515050152440/tasks/json[{\u201Cuid\u201D:\u201C49764eed1ef44817a8de410364f1244b\u201D,\u201Ctimestamp\u201D:1434108462789,\u201Ccommand\u201D:{\u201Cid\u201D:\u201Cmodeon\u201D,\u201Cparams\u201D:{}}}]\u2013EOF\u2013Pattern\u2013\nOK"}),"\n",(0,i.jsx)(n.li,{children:"Close the TCP connection\nCommand:\nAT+KTCPCLOSE=1,1\nResponse expected:\nOK"}),"\n",(0,i.jsx)(n.li,{children:"Delete the configuration\nCommand:\nAT+KTCPDEL=1\nResponse expected:\nOK\nView your application running\nYour data is now sent. You can check your data communication. Just go to\nInventory\n>\nSystems\n, then pick your own and click\nTimeline\n. That is it.\nIf you want to try it, it is all available on\nGitHub\n.\nNext Step\nContinue the tutorial\nby using tools supplied by AirVantage to test your communication with your device."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>s,x:()=>l});var a=t(6540);let i={},o=a.createContext(i);function s(e){let n=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(o.Provider,{value:n},e.children)}}}]);